r=pathlib.Path(__file__).resolve().parents[1];b=r/'build/multigrain-sustain';v=r/'validation/multigrain-sustain-2026-11-06';lock=open(r/'build/verify.lock','a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);g=json.loads((v/'evaluation.json').read_text());assert g['headroom_pass'] and g['pitch_pass'] and g['host_budget_pass'] and g['all48_transition_outputs_byte_identical']
