lib=ctypes.CDLL(str(b/'listening.so'));lib.rp_size.restype=ctypes.c_uint;lib.mg_native.argtypes=[ctypes.c_void_p,ctypes.c_uint];lib.mg_render16.argtypes=[ctypes.c_void_p,ctypes.POINTER(ctypes.c_float),ctypes.c_uint];state=ctypes.create_string_buffer(lib.rp_size());buf=(ctypes.c_float*6400)();oldpath=r/'build/residual-pilot/artifact-stages';old=json.loads((oldpath/'measurement.json').read_text());cases=[];key={};rand=random.Random(6110621)
