for pair,(j,vowel) in enumerate(items):
 lib.mg_native(state,j);lib.mg_render16(state,buf,6400);x=np.ctypeslib.as_array(buf).copy();assert np.isfinite(x).all() and max(abs(x))<.9;gain=min(.08/max(float(np.sqrt(np.mean(x*x))),1e-12),.7/max(float(max(abs(x))),1e-12));x*=gain;x[:32]*=np.linspace(0,1,32);x[-32:]*=np.linspace(1,0,32);mem=io.BytesIO()
 with wave.open(mem,'wb') as w:w.setnchannels(1);w.setsampwidth(2);w.setframerate(16000);w.writeframes(np.rint(x*32767).astype('<i2').tobytes())
 newraw=mem.getvalue();control=old['clips'][j*10+4];oldraw=(oldpath/control['file']).read_bytes();assert hashlib.sha256(oldraw).hexdigest()==control['sha256'];engines=['frozen_single','multigrain'];rand.shuffle(engines);ident=f'm{pair}';case={'id':ident,'clips':[]};key[ident]={'vowel':vowel,'engines':engines,'duration_s':.4,'new_listening_gain':gain,'old_control_sha256':control['sha256'],'new_sha256':hashlib.sha256(newraw).hexdigest()}
 for label,engine in zip(['A','B'],engines):
  raw=oldraw if engine=='frozen_single' else newraw;filename=ident+'-'+label+'.wav';(b/filename).write_bytes(raw);case['clips'].append({'label':label,'audio':'data:audio/wav;base64,'+base64.b64encode(raw).decode()})
 cases.append(case)
